create function public.request_formatting(p jsonb)returns uuid language plpgsql security definer set search_path='' as $$declare d public.question_drafts;j uuid;begin select * into d from public.question_drafts where id=(p->>'draftId')::uuid for update;perform private.require_access(d.school_id,true);if d.author_id<>auth.uid()or private.role()<>'teacher'then raise exception 'FORBIDDEN'using errcode='42501';end if;insert into public.outbox(school_id,kind,dedup_key,payload)values(d.school_id,'format','format:'||d.id||':'||d.revision,jsonb_build_object('draftId',d.id,'revision',d.revision))on conflict(dedup_key)do update set dedup_key=excluded.dedup_key returning id into j;perform private.audit(d.school_id,'question.format.requested',d.id);return j;end$$;
create function public.job_status(p jsonb)returns jsonb language plpgsql stable security definer set search_path='' as $$declare j public.outbox;begin select * into j from public.outbox where id=(p->>'id')::uuid;if j.school_id<>private.school()or not private.staff(j.school_id)then raise exception 'FORBIDDEN'using errcode='42501';end if;if j.kind='format'and not exists(select 1 from public.question_drafts where id=(j.payload->>'draftId')::uuid and author_id=auth.uid())then raise exception 'FORBIDDEN'using errcode='42501';end if;return jsonb_build_object('id',j.id,'kind',j.kind,'status',j.status,'attempts',j.attempts,'errorCode',j.error_code,'createdAt',j.created_at);end$$;
create function public.formatting_input(p jsonb)returns jsonb language sql stable security definer set search_path='' as $$select jsonb_build_object('rawText',raw_text,'revision',revision)from public.question_drafts where id=(p->>'draftId')::uuid$$;
create function public.runtime_formatted(p jsonb)returns void language plpgsql security definer set search_path='' as $$declare j public.outbox;begin select * into j from public.outbox where id=(p->>'jobId')::uuid and kind='format'and run_token=(p->>'runToken')::uuid;if not found then return;end if;update public.question_drafts set content=p->'content',revision=revision+1 where id=(j.payload->>'draftId')::uuid and revision=(j.payload->>'revision')::int;end$$;
create function public.school_report(p jsonb)returns jsonb language plpgsql stable security definer set search_path='' as $$declare s uuid:=private.school();rows jsonb;begin perform private.require_access(s);if private.role()not in('teacher','administrator')then raise exception 'FORBIDDEN'using errcode='42501';end if;select coalesce(jsonb_agg(r),'[]')into rows from(select rr.student_id,e.subject,e.class_id,count(*)as published_assessments,sum(rr.total)as earned,sum(rr.maximum)as maximum,100.0*sum(rr.total)/nullif(sum(rr.maximum),0)as weighted_percentage,max(rr.published_at)as source_updated_at from public.results rr join public.exam_versions e on e.id=rr.version_id join public.classes c on c.id=e.class_id where rr.school_id=s and private.report_result(rr.version_id,rr.student_id)and(p->>'classId'is null or e.class_id=(p->>'classId')::uuid)and(p->>'subject'is null or e.subject=p->>'subject')and(p->>'academicYear'is null or c.academic_year=p->>'academicYear')and(p->>'from'is null or rr.published_at>=(p->>'from')::timestamptz)and(p->>'to'is null or rr.published_at<(p->>'to')::timestamptz)group by rr.student_id,e.subject,e.class_id order by rr.student_id,e.subject limit least(coalesce((p->>'limit')::int,25),100)offset greatest(coalesce((p->>'offset')::int,0),0))r;return jsonb_build_object('rows',rows,'filters',p,'generatedAt',now());end$$;
create function public.student_home(p jsonb)returns jsonb language plpgsql stable security definer set search_path='' as $$declare s uuid:=private.school();u uuid:=auth.uid();begin perform private.require_access(s);perform private.learning_access();if private.role()<>'student'then raise exception 'FORBIDDEN'using errcode='42501';end if;return jsonb_build_object('generatedAt',now(),'groups',(select coalesce(jsonb_agg(jsonb_build_object('id',g.id,'title',g.title,'subject',g.subject,'teacherId',g.teacher_id,'unreadPosts',(select count(*)from public.posts po where po.group_id=g.id and not po.deleted and not exists(select 1 from public.post_reads where post_id=po.id and student_id=u)))),'[]')from public.groups g join public.group_memberships gm on gm.group_id=g.id where gm.student_id=u and gm.state='active'and not g.archived),'recentResults',(select coalesce(jsonb_agg(x),'[]')from(select id,version_id,total,maximum,published_at from public.results where student_id=u order by published_at desc limit 10)x),'queryCounts',(select coalesce(jsonb_object_agg(state,n),'{}')from(select state,count(*)as n from public.queries where student_id=u group by state)x),'insight',(select jsonb_build_object('status',status,'content',case when suppressed then null else content end,'correction',correction,'updatedAt',updated_at)from public.student_insights where student_id=u));end$$;
create function public.read_post(p jsonb)returns void language plpgsql security definer set search_path='' as $$declare po public.posts;begin select * into po from public.posts where id=(p->>'id')::uuid;if not private.can_group(po.group_id)or private.role()<>'student'then raise exception 'FORBIDDEN'using errcode='42501';end if;insert into public.post_reads values(po.school_id,po.id,auth.uid(),now())on conflict do nothing;end$$;
revoke execute on function public.request_formatting(jsonb),public.job_status(jsonb),public.formatting_input(jsonb),public.runtime_formatted(jsonb),public.school_report(jsonb),public.student_home(jsonb),public.read_post(jsonb)from public,anon,authenticated;grant execute on function public.request_formatting(jsonb),public.job_status(jsonb),public.school_report(jsonb),public.student_home(jsonb),public.read_post(jsonb)to authenticated;grant execute on function public.formatting_input(jsonb),public.runtime_formatted(jsonb)to service_role;
